- In getTasksForStatus() (line 311-321): After creating each TaskItem, store
  TaskItem -> StatusGroupItem mapping. Need to pass the StatusGroupItem as a
  parameter to track the parent.
- In getChildrenForTask() (line 331-346): After creating each ActionItem and
  FileItem, store child -> TaskItem mapping in childToTask Map.

For getTasksForStatus, modify to accept StatusGroupItem parameter:
```typescript
function getTasksForStatus(status: TaskStatus, parentGroup: StatusGroupItem): TaskItem[] {
  const tasks = deps.loadTasks();
  const items = tasks
    .filter((t) => t.status === status)
    .map((t) => new TaskItem(t, deps.checkTaskFiles(t.taskPath), deps.getAllActions(t)));

  // Update cache and track parent
  items.forEach((item) => {
    cachedTaskItems.set(item.task.id, item);
    taskToStatusGroup.set(item.task.id, parentGroup);
  });

  return items;
}
```

For getChildrenForTask, add parent tracking:
```typescript
function getChildrenForTask(taskItem: TaskItem): (ActionItem | FileItem)[] {
  const children: (ActionItem | FileItem)[] = [];

  taskItem.actions.forEach((action, index) => {
    const actionItem = new ActionItem(taskItem.task.id, action, index === 0);
    children.push(actionItem);
    childToTask.set(actionItem, taskItem);
  });

  const fileItems = getFilesForTask(taskItem.task.taskPath);
  fileItems.forEach((fileItem) => {
    children.push(fileItem);
    childToTask.set(fileItem, taskItem);
  });

  return children;
}
```

Update getChildren() call site to pass parent:
